"""Migrated case_lifecycle workflow for CASE_MASTER."""

from __future__ import annotations


def _value(record: dict, field: str) -> str:
    """Return a field value using legacy empty-string semantics for missing values."""
    value = record.get(field, "")
    return "" if value is None else str(value)


def _nvl(value: str, default: str) -> str:
    """VRL NVL: empty and missing values select the default."""
    return default if value == "" else value


def fire(state: str, event: str, record: dict) -> dict:
    """Dispatch one explicit case_lifecycle workflow event."""
    result_record = dict(record)

    matched_transition: tuple[str, tuple[tuple[str, str], ...], tuple[str, ...], tuple[str, ...]] | None = None

    if state == "N" and event == "assign" and _value(result_record, "OWNER_UID") != "":
        matched_transition = ("A", (), ("CASE_ASSIGN",), ())

    elif state == "N" and event == "auto_escalate":
        matched_transition = (
            "A",
            (
                ("ESC_FLG", "Y"),
                ("SEV_CD", "=NVL(SEV_CD,'3')"),
            ),
            ("CASE_ESC",),
            ("escalation",),
        )

    elif state == "A" and event == "auto_escalate" and _value(result_record, "ESC_FLG") != "Y":
        matched_transition = (
            "A",
            (("ESC_FLG", "Y"),),
            ("CASE_ESC",),
            ("escalation",),
        )

    elif state == "A" and event == "await_customer":
        matched_transition = ("P", (), ("CASE_PEND",), ())

    elif state == "P" and event == "customer_reply":
        matched_transition = ("A", (), (), ())

    elif state == "A" and event == "resolve" and _value(result_record, "RES_DT") != "00000000":
        matched_transition = ("R", (), ("CASE_RES",), ())

    elif state == "R" and event == "close":
        matched_transition = ("X", (), ("CASE_CLOSE",), ())

    elif state == "R" and event == "reopen":
        matched_transition = (
            "A",
            (("RES_DT", "00000000"),),
            ("CASE_REOPEN",),
            (),
        )

    if matched_transition is None:
        return {
            "state": state,
            "record": result_record,
            "audits": ["WF_NOMATCH"],
            "notifies": [],
            "matched": False,
        }

    next_state, sets, audits, notifies = matched_transition
    for field, value in sets:
        if value == "=NVL(SEV_CD,'3')":
            result_record[field] = _nvl(_value(result_record, "SEV_CD"), "3")
        else:
            result_record[field] = value

    return {
        "state": next_state,
        "record": result_record,
        "audits": list(audits),
        "notifies": list(notifies),
        "matched": True,
    }
